'use client';

import { useEffect } from 'react';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedQuietOf,
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import {
  Stepper,
  StepperIndicator,
  StepperItem,
  StepperSeparator,
  StepperTrigger,
} from '@/registry/ndeko/ui/stepper';

import {
  indexOfStep,
  stepOf,
  STEPS,
  type Fields,
  type RoleId,
  type SourceId,
  type StepId,
} from './data';
import { ReviewStep, Success } from './review-step';
import {
  CREATE_MS,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  TOTAL,
  type FinishStatus,
  type WizardAction,
} from './session';
import { firstErrorOf } from './validate';
import { SourceStep, TeamStep, WorkspaceStep } from './wizard-steps';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const FINISH_STATE: Record<FinishStatus, MorphState> = {
  idle: 'idle',
  creating: 'busy',
  created: 'done',
};

const FINISH_LABELS: Record<MorphState, string> = {
  idle: 'Create workspace',
  busy: 'Creating',
  done: 'Created',
};

/** What the wizard hands over once the workspace is created. */
export type WorkspaceSetup = {
  name: string;
  slug: string;
  /** Nothing when the step was skipped. */
  source: SourceId | null;
  connection: string | null;
  invites: string[];
  role: RoleId;
};

function setupOf(fields: Fields, skipped: StepId[]): WorkspaceSetup {
  const setup: WorkspaceSetup = {
    name: fields.name.trim(),
    slug: fields.slug,
    source: null,
    connection: null,
    invites: [],
    role: fields.role,
  };
  if (!skipped.includes('source')) {
    setup.source = fields.source;
    setup.connection = fields.connection.trim();
  }
  if (!skipped.includes('team')) {
    setup.invites = fields.invites;
  }
  return setup;
}

/** Once the workspace exists every step counts as done: the stepper is told the step after the last. */
function activeNumberOf(stepIndex: number, isCreated: boolean) {
  if (isCreated) {
    return TOTAL + 1;
  }
  return stepIndex + 1;
}

function currentStepOf(isCurrent: boolean): 'step' | undefined {
  if (isCurrent) {
    return 'step';
  }
  return undefined;
}

/** A step opened from the review leads back to it. */
function nextLabelOf(isReturning: boolean) {
  if (isReturning) {
    return 'Back to review';
  }
  return 'Next';
}

/** The first step is there when the page loads. The ones that follow fade in. */
function arrivalOf(hasMoved: boolean) {
  if (hasMoved) {
    return 'transition-opacity duration-200 starting:opacity-0';
  }
  return undefined;
}

function stepLineOf(stepIndex: number, isOptional: boolean) {
  const line = `Step ${stepIndex + 1} of ${TOTAL}`;
  if (isOptional) {
    return `${line}, optional`;
  }
  return line;
}

export type Onboarding02Props = {
  /**
   * Keeps the step in the hash of the address, and follows the hash when it changes. It waits for a
   * person: the demonstration never writes to the address of the page.
   */
  syncHash?: boolean;
  /** Nothing calls a network. A real app creates the workspace here. */
  onFinish?: (setup: WorkspaceSetup) => void;
};

export default function Onboarding02({
  syncHash = false,
  onFinish,
}: Onboarding02Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const step = stepOf(state.step);
  const stepIndex = indexOfStep(state.step);
  const isCreated = state.finish === 'created';
  const isCreating = state.finish === 'creating';
  const isEditable = state.finish === 'idle';
  const isReview = state.step === 'review';
  const canGoBack = stepIndex > 0;
  const canSkip = step.isOptional;
  const activeNumber = activeNumberOf(stepIndex, isCreated);
  const shouldSyncHash = syncHash && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;
  useEffect(() => {
    if (!shouldSyncHash) {
      return;
    }
    const hash = `#${state.step}`;
    if (window.location.hash !== hash) {
      window.history.replaceState(null, '', hash);
    }
  }, [shouldSyncHash, state.step]);

  useEffect(() => {
    if (!shouldSyncHash) {
      return;
    }
    function followHash() {
      const id = window.location.hash.slice(1);
      const target = STEPS.find((candidate) => candidate.id === id);
      if (target) {
        act({ type: 'jumped', step: target.id });
      }
    }
    window.addEventListener('hashchange', followHash);
    return () => window.removeEventListener('hashchange', followHash);
  }, [shouldSyncHash, act]);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /**
   * Works out where an action leads before it is sent: a step that changes takes the focus to its
   * heading, an entry that is refused takes it to the first field at fault.
   */
  function actAndFollow(action: WizardAction) {
    const after = reducer(state, action);
    act(action);
    if (after.step !== state.step) {
      focusLater('[data-step-heading]');
      return;
    }
    const wasRefused = after.attempts !== state.attempts;
    const refusal = firstErrorOf(after.errors);
    if (wasRefused && refusal) {
      focusLater(`[data-field="${refusal.field}"]`);
    }
  }

  const stepBody = {
    fields: state.fields,
    errors: state.errors,
    attempts: state.attempts,
    pressed,
    onAction: actAndFollow,
  };

  /** The button leaves with the review once the workspace exists: a focus that sat on it goes to the message. */
  function create(setup: WorkspaceSetup) {
    const finishButton = ref.current?.querySelector('[data-finish]');
    const hadFocus = finishButton === document.activeElement;
    act({ type: 'created' });
    onFinish?.(setup);
    if (finishButton && hadFocus) {
      focusLater('[data-success]');
    }
  }

  function finish() {
    if (!isEditable) {
      return;
    }
    const setup = setupOf(state.fields, state.skipped);
    act({ type: 'finishPressed' });
    schedule(() => create(setup), CREATE_MS);
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isReview) {
      finish();
      return;
    }
    actAndFollow({ type: 'nextPressed' });
  }

  function jumpToNumber(number: number) {
    const target = STEPS[number - 1];
    if (target) {
      actAndFollow({ type: 'jumped', step: target.id });
    }
  }

  /** The chip takes its button with it, so the focus goes back to the address box. */
  function removeInvite(address: string) {
    act({ type: 'inviteRemoved', address });
    focusLater('[data-field="invites"]');
  }

  /** A workspace on its way belongs to the round it was asked for in. */
  function replay() {
    clearAll();
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container flex min-h-dvh w-full flex-col items-center p-4 @2xl:p-8'
      >
        <div className='flex w-full max-w-xl flex-col gap-5 @2xl:pt-4'>
          <header className='flex min-h-8 items-center gap-3'>
            <h1 className='min-w-0 flex-1 text-lg font-semibold text-balance'>
              Set up a workspace
            </h1>
            <ReplayButton
              isShown={canReplay}
              onReplay={replay}
              label='Replay'
            />
          </header>

          <nav aria-label='Setup steps'>
            <Stepper value={activeNumber} onValueChange={jumpToNumber}>
              {STEPS.map((candidate, index) => {
                const number = index + 1;
                const isLast = number === TOTAL;
                const isAhead = index > state.furthest;
                const isCurrent = index === stepIndex && !isCreated;
                return (
                  <StepperItem
                    key={candidate.id}
                    step={number}
                    disabled={isAhead || !isEditable}
                    loading={isCreating}
                    className='not-last:flex-1'
                  >
                    <StepperTrigger
                      aria-current={currentStepOf(isCurrent)}
                      className='gap-2'
                    >
                      <StepperIndicator />
                      <span className='sr-only text-[13px] font-medium whitespace-nowrap @md:not-sr-only'>
                        {candidate.label}
                      </span>
                    </StepperTrigger>
                    {!isLast && <StepperSeparator className='mx-2' />}
                  </StepperItem>
                );
              })}
            </Stepper>
          </nav>

          <section
            aria-label='Workspace setup'
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
          >
            <AnimatedSize>
              {isCreated && (
                <Success
                  fields={state.fields}
                  skipped={state.skipped}
                  onRestart={() => actAndFollow({ type: 'restarted' })}
                />
              )}
              {!isCreated && (
                <form
                  key={state.step}
                  noValidate
                  onSubmit={submit}
                  className={cn(
                    'flex flex-col gap-5',
                    arrivalOf(state.moves > 0)
                  )}
                >
                  <div className='flex flex-col gap-1'>
                    <p className='text-muted-foreground text-xs tabular-nums'>
                      {stepLineOf(stepIndex, step.isOptional)}
                    </p>
                    <h2
                      data-step-heading
                      tabIndex={-1}
                      className='focus-visible:ring-ring/25 rounded-sm text-base font-semibold text-balance outline-none focus-visible:ring-[3px]'
                    >
                      {step.title}
                    </h2>
                    <p className='text-muted-foreground text-[13px] text-pretty'>
                      {step.lead}
                    </p>
                  </div>

                  {state.step === 'workspace' && (
                    <WorkspaceStep {...stepBody} />
                  )}
                  {state.step === 'source' && <SourceStep {...stepBody} />}
                  {state.step === 'team' && (
                    <TeamStep {...stepBody} onRemoveInvite={removeInvite} />
                  )}
                  {isReview && (
                    <ReviewStep
                      fields={state.fields}
                      skipped={state.skipped}
                      isLocked={!isEditable}
                      pressed={pressed}
                      onEdit={(target) =>
                        actAndFollow({ type: 'jumped', step: target })
                      }
                    />
                  )}

                  <div className='flex flex-wrap items-center gap-2'>
                    {canGoBack && (
                      <Button
                        type='button'
                        variant='ghost'
                        disabled={!isEditable}
                        onClick={() => actAndFollow({ type: 'backPressed' })}
                      >
                        Back
                      </Button>
                    )}
                    <span className='flex-1' />
                    {canSkip && (
                      <Button
                        type='button'
                        variant='ghost'
                        onClick={() => actAndFollow({ type: 'skipPressed' })}
                        className={cn(
                          'text-muted-foreground',
                          pressedQuietOf(pressed === 'skip')
                        )}
                      >
                        Skip
                      </Button>
                    )}
                    {!isReview && (
                      <Button
                        type='submit'
                        className={pressedSolidOf(pressed === 'next')}
                      >
                        {nextLabelOf(state.isReturning)}
                      </Button>
                    )}
                    {isReview && (
                      <MorphButton
                        type='submit'
                        data-finish
                        state={FINISH_STATE[state.finish]}
                        labels={FINISH_LABELS}
                        className={pressedSolidOf(pressed === 'finish')}
                      />
                    )}
                  </div>
                </form>
              )}
            </AnimatedSize>
          </section>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useId } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { MailIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import { Label, LABEL_RECIPE } from '@/registry/ndeko/ui/label';
import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';
import { Segments } from '@/registry/ndeko/ui/segments';

import { ROLES, SOURCES, URL_PREFIX, type Fields } from './data';
import type { WizardAction } from './session';
import type { Errors } from './validate';

/** A tray inside the card, tinted when its source is the one picked. The whole tray answers the press. */
const CHOICE =
  'bg-foreground/[0.04] has-data-checked:bg-primary/[0.08] relative flex items-center gap-3 rounded-lg p-3 transition-[background-color,scale] duration-150';

/** Someone invited has not joined yet: a dashed slot with an envelope, since nobody is there. */
const INVITED =
  'hairline-border border-foreground/25 flex h-7 max-w-full items-center gap-1.5 rounded-full border-dashed ps-2.5 pe-0.5 text-xs transition-opacity duration-200 starting:opacity-0';

const REMOVE =
  'focus-visible:ring-ring/25 hover:bg-foreground/[0.08] text-muted-foreground hover:text-foreground flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full transition-colors duration-150 outline-none focus-visible:ring-[3px]';

const LONE_ERROR =
  'text-destructive-ink text-xs transition-[opacity,translate] duration-200 ease-(--ease-out-strong) starting:-translate-y-0.5 starting:opacity-0';

/** A space, a comma or a semicolon ends an address as it is typed. */
const ENDS_AN_ADDRESS = /[\s,;]$/;

export type StepBodyProps = {
  fields: Fields;
  errors: Errors;
  /** Counts the refused entries: a message that comes back after a new try arrives again. */
  attempts: number;
  pressed: string | null;
  onAction: (action: WizardAction) => void;
};

export function WorkspaceStep({
  fields,
  errors,
  attempts,
  onAction,
}: StepBodyProps) {
  return (
    <div className='flex flex-col gap-4'>
      <Field invalid={Boolean(errors.name)}>
        <FieldLabel>Workspace name</FieldLabel>
        <Input
          data-field='name'
          autoComplete='organization'
          placeholder='The name of your company or team'
          value={fields.name}
          onChange={(event) =>
            onAction({
              type: 'typed',
              field: 'name',
              value: event.target.value,
            })
          }
        />
        {errors.name && (
          <FieldError key={attempts} match>
            {errors.name}
          </FieldError>
        )}
      </Field>
      <Field invalid={Boolean(errors.slug)}>
        <FieldLabel>Workspace address</FieldLabel>
        <div className='flex items-center gap-2'>
          <span className='text-muted-foreground shrink-0 text-[13px]'>
            {URL_PREFIX}
          </span>
          <Input
            data-field='slug'
            autoComplete='off'
            autoCapitalize='none'
            spellCheck={false}
            placeholder='your-workspace'
            value={fields.slug}
            onChange={(event) =>
              onAction({
                type: 'typed',
                field: 'slug',
                value: event.target.value,
              })
            }
          />
        </div>
        {errors.slug && (
          <FieldError key={attempts} match>
            {errors.slug}
          </FieldError>
        )}
        {!errors.slug && (
          <FieldDescription>
            It follows the name until you change it
          </FieldDescription>
        )}
      </Field>
    </div>
  );
}

/** The first source carries the mark the focus goes to when no source is picked. */
function fieldMarkOf(index: number) {
  if (index === 0) {
    return 'source';
  }
  return undefined;
}

function describedByOf(hasError: boolean, errorId: string) {
  if (hasError) {
    return errorId;
  }
  return undefined;
}

export function SourceStep({
  fields,
  errors,
  attempts,
  pressed,
  onAction,
}: StepBodyProps) {
  const groupId = useId();
  const errorId = `${groupId}-error`;
  const hasSourceError = Boolean(errors.source);

  function pick(value: unknown) {
    const source = SOURCES.find((candidate) => candidate.id === value);
    if (source) {
      onAction({ type: 'sourcePicked', source: source.id });
    }
  }

  return (
    <div className='flex flex-col gap-4'>
      <div className='flex flex-col gap-2'>
        <RadioGroup
          aria-label='Data source'
          aria-describedby={describedByOf(hasSourceError, errorId)}
          value={fields.source ?? ''}
          onValueChange={pick}
          className='grid-cols-1 gap-2 @md:grid-cols-2'
        >
          {SOURCES.map((source, index) => {
            const itemId = `${groupId}-${source.id}`;
            return (
              <div
                key={source.id}
                className={cn(
                  CHOICE,
                  pressedQuietOf(pressed === `source-${source.id}`)
                )}
              >
                <RadioGroupItem
                  id={itemId}
                  value={source.id}
                  data-field={fieldMarkOf(index)}
                  className='order-1 after:absolute after:inset-0 after:rounded-lg'
                />
                <BrandTile brand={source.brand} size='lg' />
                <div className='flex min-w-0 flex-1 flex-col gap-1'>
                  <Label htmlFor={itemId}>{source.name}</Label>
                  <p className='text-muted-foreground text-xs'>{source.kind}</p>
                </div>
              </div>
            );
          })}
        </RadioGroup>
        {errors.source && (
          <p key={attempts} id={errorId} className={LONE_ERROR}>
            {errors.source}
          </p>
        )}
      </div>
      <Field invalid={Boolean(errors.connection)}>
        <FieldLabel>Connection name</FieldLabel>
        <Input
          data-field='connection'
          autoComplete='off'
          value={fields.connection}
          onChange={(event) =>
            onAction({
              type: 'typed',
              field: 'connection',
              value: event.target.value,
            })
          }
        />
        {errors.connection && (
          <FieldError key={attempts} match>
            {errors.connection}
          </FieldError>
        )}
      </Field>
    </div>
  );
}

type TeamStepProps = StepBodyProps & {
  onRemoveInvite: (address: string) => void;
};

export function TeamStep({
  fields,
  errors,
  attempts,
  pressed,
  onAction,
  onRemoveInvite,
}: TeamStepProps) {
  const hasInvites = fields.invites.length > 0;

  function typeAddress(value: string) {
    onAction({ type: 'typed', field: 'inviteDraft', value });
    if (ENDS_AN_ADDRESS.test(value)) {
      onAction({ type: 'inviteCommitted' });
    }
  }

  /** Enter adds what the box holds. On an empty box it is left alone, and goes on to the next step. */
  function addOnEnter(event: React.KeyboardEvent<HTMLInputElement>) {
    const isBoxEmpty = fields.inviteDraft.trim() === '';
    if (event.key !== 'Enter' || isBoxEmpty) {
      return;
    }
    event.preventDefault();
    onAction({ type: 'inviteCommitted' });
  }

  function changeRole(role: Fields['role']) {
    onAction({ type: 'rolePicked', role });
  }

  return (
    <div className='flex flex-col gap-4'>
      <Field invalid={Boolean(errors.invites)}>
        <FieldLabel>Email addresses</FieldLabel>
        <div className='flex items-center gap-2'>
          <Input
            data-field='invites'
            inputMode='email'
            autoComplete='off'
            autoCapitalize='none'
            spellCheck={false}
            placeholder='name@company.com'
            value={fields.inviteDraft}
            onChange={(event) => typeAddress(event.target.value)}
            onKeyDown={addOnEnter}
          />
          <Button
            type='button'
            variant='outline'
            onClick={() => onAction({ type: 'inviteCommitted' })}
            className={cn('shrink-0', pressedQuietOf(pressed === 'add-invite'))}
          >
            Add
          </Button>
        </div>
        {errors.invites && (
          <FieldError key={attempts} match>
            {errors.invites}
          </FieldError>
        )}
        {!errors.invites && (
          <FieldDescription>
            Press Enter after each address, or paste several at once
          </FieldDescription>
        )}
      </Field>
      <div className='flex min-h-7 items-center'>
        {!hasInvites && (
          <p className='text-muted-foreground text-xs'>Nobody is invited yet</p>
        )}
        {hasInvites && (
          <ul
            aria-label='People to invite'
            className='flex min-w-0 flex-wrap gap-1.5'
          >
            {fields.invites.map((address) => (
              <li key={address} className={INVITED}>
                <MailIcon
                  aria-hidden='true'
                  className='text-muted-foreground size-3.5 shrink-0'
                />
                <span className='min-w-0 truncate'>{address}</span>
                <button
                  type='button'
                  aria-label={`Remove ${address}`}
                  onClick={() => onRemoveInvite(address)}
                  className={REMOVE}
                >
                  <XIcon className='size-3.5' />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
      <div className='flex flex-col items-start gap-1.5'>
        <p className={LABEL_RECIPE}>They join as</p>
        <Segments
          value={fields.role}
          segments={ROLES}
          onValueChange={changeRole}
          label='Role of the people you invite'
        />
      </div>
    </div>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';

import {
  roleLabelOf,
  sourceOf,
  stepOf,
  URL_PREFIX,
  type Fields,
  type StepId,
} from './data';
import { CalmCheck } from './drawn-check';

/** The source the workspace starts with: none when the step was skipped. */
function keptSourceOf(fields: Fields, skipped: StepId[]) {
  if (skipped.includes('source')) {
    return null;
  }
  return sourceOf(fields.source);
}

function peopleLineOf(fields: Fields) {
  const count = fields.invites.length;
  const role = roleLabelOf(fields.role);
  if (count === 1) {
    return `1 person invited as ${role}`;
  }
  return `${count} people invited as ${role}`;
}

type ReviewRowProps = {
  step: StepId;
  isLocked: boolean;
  isPressed: boolean;
  onEdit: (step: StepId) => void;
  children: React.ReactNode;
};

/** One thing the wizard will create, with the way back to the step that sets it. */
function ReviewRow({
  step,
  isLocked,
  isPressed,
  onEdit,
  children,
}: ReviewRowProps) {
  const label = stepOf(step).label;

  return (
    <div className='bg-foreground/[0.04] flex flex-col gap-1 rounded-lg p-3'>
      <dt className='text-muted-foreground text-xs'>{label}</dt>
      <dd className='flex items-start gap-3'>
        <div className='flex min-w-0 flex-1 flex-col gap-0.5 text-[13px]'>
          {children}
        </div>
        <Button
          type='button'
          variant='link'
          size='sm'
          aria-label={`Edit ${label}`}
          disabled={isLocked}
          onClick={() => onEdit(step)}
          className={pressedQuietOf(isPressed)}
        >
          Edit
        </Button>
      </dd>
    </div>
  );
}

function Skipped() {
  return <p className='text-muted-foreground'>Skipped. You can do it later</p>;
}

type ReviewStepProps = {
  fields: Fields;
  skipped: StepId[];
  /** While the workspace is being created nothing can be changed any more. */
  isLocked: boolean;
  pressed: string | null;
  onEdit: (step: StepId) => void;
};

export function ReviewStep({
  fields,
  skipped,
  isLocked,
  pressed,
  onEdit,
}: ReviewStepProps) {
  const source = keptSourceOf(fields, skipped);
  const isTeamSkipped = skipped.includes('team') || fields.invites.length === 0;

  return (
    <dl className='flex flex-col gap-2'>
      <ReviewRow
        step='workspace'
        isLocked={isLocked}
        isPressed={pressed === 'edit-workspace'}
        onEdit={onEdit}
      >
        <p className='truncate font-medium'>{fields.name.trim()}</p>
        <p className='text-muted-foreground truncate text-xs'>
          {URL_PREFIX}
          {fields.slug}
        </p>
      </ReviewRow>
      <ReviewRow
        step='source'
        isLocked={isLocked}
        isPressed={pressed === 'edit-source'}
        onEdit={onEdit}
      >
        {!source && <Skipped />}
        {source && (
          <p className='flex min-w-0 items-center gap-2 font-medium'>
            <BrandTile brand={source.brand} />
            <span className='truncate'>
              {source.name}, as {fields.connection.trim()}
            </span>
          </p>
        )}
      </ReviewRow>
      <ReviewRow
        step='team'
        isLocked={isLocked}
        isPressed={pressed === 'edit-team'}
        onEdit={onEdit}
      >
        {isTeamSkipped && <Skipped />}
        {!isTeamSkipped && (
          <>
            <p className='font-medium'>{peopleLineOf(fields)}</p>
            <p className='text-muted-foreground text-xs break-words'>
              {fields.invites.join(', ')}
            </p>
          </>
        )}
      </ReviewRow>
    </dl>
  );
}

/** What the workspace starts with, in one or two short sentences. */
function summaryOf(fields: Fields, skipped: StepId[]) {
  const sentences = [`It lives at ${URL_PREFIX}${fields.slug}.`];
  const source = keptSourceOf(fields, skipped);
  if (source) {
    sentences.push(`${source.name} is connected.`);
  }
  const hasTeam = fields.invites.length > 0 && !skipped.includes('team');
  if (hasTeam) {
    sentences.push(`${peopleLineOf(fields)}.`);
  }
  return sentences.join(' ');
}

type SuccessProps = {
  fields: Fields;
  skipped: StepId[];
  onRestart: () => void;
};

export function Success({ fields, skipped, onRestart }: SuccessProps) {
  return (
    <div
      data-success
      tabIndex={-1}
      className='flex flex-col items-start gap-4 py-1 transition-opacity duration-300 outline-none starting:opacity-0'
